begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
grant usage on schema extensions to anon, authenticated;
select plan(28);
insert into auth.users(id) values ('11111111-1111-4111-8111-111111111111'), ('22222222-2222-4222-8222-222222222222'), ('33333333-3333-4333-8333-333333333333');
insert into public.documents(id,owner_id,body) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','11111111-1111-4111-8111-111111111111','private A');
select ok((select relrowsecurity from pg_class where oid = 'public.documents'::regclass), 'RLS is enabled');
reset role;
select set_config('request.jwt.claims', '{"sub":"","role":"anon"}', true);
set local role anon;
select throws_ok($$select * from public.documents$$, '42501', null, 'anon read denied by grants');
select throws_ok($$insert into public.documents(owner_id,body) values ('11111111-1111-4111-8111-111111111111','forged')$$, '42501', null, 'anon insert denied by grants');
select throws_ok($$update public.documents set body='forged'$$, '42501', null, 'anon update denied by grants');
select throws_ok($$delete from public.documents$$, '42501', null, 'anon delete denied by grants');
reset role;
select set_config('request.jwt.claims', '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}', true);
set local role authenticated;
select is((select body from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 'private A', 'owner can read');
select results_eq($$update public.documents set body='updated A' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' returning body$$, $$values ('updated A'::text)$$, 'owner can update');
select throws_ok($$update public.documents set owner_id='22222222-2222-4222-8222-222222222222' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'$$, '42501', null, 'owner cannot transfer ownership');
reset role;
select set_config('request.jwt.claims', '{"sub":"22222222-2222-4222-8222-222222222222","role":"authenticated"}', true);
set local role authenticated;
select is((select count(*) from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 0::bigint, 'B cannot read A by direct ID');
select is((select count(*) from public.documents), 0::bigint, 'B cannot enumerate A');
select results_eq($$with changed as (update public.documents set body='attack' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' returning id) select count(*) from changed$$, $$values (0::bigint)$$, 'B cannot update A');
select results_eq($$with removed as (delete from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' returning id) select count(*) from removed$$, $$values (0::bigint)$$, 'B cannot delete A');
select throws_ok($$insert into public.documents(owner_id,body) values ('11111111-1111-4111-8111-111111111111','forged')$$, '42501', null, 'B cannot insert as A');
select lives_ok($$insert into public.documents(owner_id,body) values ('22222222-2222-4222-8222-222222222222','B own')$$, 'B can insert own row');
select is((select body from public.documents where owner_id='22222222-2222-4222-8222-222222222222'), 'B own', 'B can read own row');
select throws_ok($$insert into public.documents(id,owner_id,body) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa','22222222-2222-4222-8222-222222222222','probe')$$, '42501', null, 'B cannot supply existing or unused ID');
select throws_ok($$update public.documents set id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' where owner_id='22222222-2222-4222-8222-222222222222'$$, '42501', null, 'B cannot change ID to existing or unused ID');
select throws_ok($$insert into public.documents(id,owner_id,body) values ('dddddddd-dddd-4ddd-8ddd-dddddddddddd','22222222-2222-4222-8222-222222222222','probe')$$, '42501', null, 'B cannot supply existing or unused ID');
select throws_ok($$update public.documents set id='dddddddd-dddd-4ddd-8ddd-dddddddddddd' where owner_id='22222222-2222-4222-8222-222222222222'$$, '42501', null, 'B cannot change ID to existing or unused ID');
select results_eq($$update public.documents set body='B updated' where owner_id='22222222-2222-4222-8222-222222222222' returning body$$, $$values ('B updated'::text)$$, 'B can update own row');
select results_eq($$with removed as (delete from public.documents where owner_id='22222222-2222-4222-8222-222222222222' returning id) select count(*) from removed$$, $$values (1::bigint)$$, 'B can delete own row');
reset role;
select set_config('request.jwt.claims', '{"sub":"33333333-3333-4333-8333-333333333333","role":"authenticated"}', true);
set local role authenticated;
select is((select count(*) from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 0::bigint, 'admin account has no implicit bypass');
select results_eq($$with changed as (update public.documents set body='admin attack' where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' returning id) select count(*) from changed$$, $$values (0::bigint)$$, 'admin cannot update A');
select results_eq($$with removed as (delete from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' returning id) select count(*) from removed$$, $$values (0::bigint)$$, 'admin cannot delete A');
select throws_ok($$insert into public.documents(owner_id,body) values ('11111111-1111-4111-8111-111111111111','forged')$$, '42501', null, 'admin cannot insert as A');
reset role;
select set_config('request.jwt.claims', '{"sub":"11111111-1111-4111-8111-111111111111","role":"authenticated"}', true);
set local role authenticated;
select is((select body from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'), 'updated A', 'denied operations left A unchanged');
select results_eq($$with removed as (delete from public.documents where id='aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa' returning id) select count(*) from removed$$, $$values (1::bigint)$$, 'A can delete own row');
select lives_ok($$insert into public.documents(owner_id,body) values ('11111111-1111-4111-8111-111111111111','new A')$$, 'A can insert own row');
reset role;
select * from finish();
rollback;
